              />
            </Field>
            <Field label="To">
              <Input
                type="date"
                value={value.dateTo ?? ""}
                onChange={(e) => onChange({ ...value, dateTo: e.target.value || null })}
              />
            </Field>
          </div>
        </div>
      )}
    </div>
  );
}

